import assert from 'node:assert/strict';
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { dirname, resolve, join } from 'node:path';
import { createHash } from 'node:crypto';
import { loadPackageFromDirectory, validatePackage } from '@jvm-expert/core';
import { NodeFileSystem } from '@jvm-expert/node';
const root = 'skills/architecture-testing';
const loaded = await loadPackageFromDirectory(new NodeFileSystem(), root, { strict: true });
const report = validatePackage(loaded.pkg, { directoryName: 'architecture-testing' });
assert.deepEqual([...loaded.issues, ...report.issues], []);
const links = [];
for (const file of loaded.pkg.files.filter(file => file.path.endsWith('.md'))) {
 const source = readFileSync(resolve(root, file.path), 'utf8');
 for (const match of source.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)) {
  const target = match[1].replace(/^<|>$/g, '');
  if (/^(https?:|#)/.test(target)) continue;
  assert.ok(existsSync(resolve(root, dirname(file.path), target.split('#')[0])), target);
  links.push({ from: file.path, target });
 }
}
const baseline = JSON.parse(readFileSync('docs/skill-validation/wave4-2026-10-16/baseline.json', 'utf8')).packages.find(row => row.name === 'architecture-testing');
const final = baseline.files.map(file => ({ path: file.path, sha256: createHash('sha256').update(readFileSync(file.path)).digest('hex') }));
const changed = final.filter(file => file.sha256 !== baseline.files.find(original => original.path === file.path).sha256).map(file => file.path);
assert.deepEqual(changed.sort(), ['skills/architecture-testing/references/boundary-and-contract-tests.md', 'skills/architecture-testing/references/persistence-and-concurrency-tests.md', 'skills/architecture-testing/skill.yaml']);
const base = 'C:/Users/robso/AppData/Local/Temp/skills-wave4-validation-Ceekn9/architecture-testing-artifacts';
const walk = (dir, relative = '') => readdirSync(dir, { withFileTypes: true }).flatMap(entry => entry.isDirectory() ? walk(join(dir, entry.name), join(relative, entry.name)) : [join(relative, entry.name)]);
const caseFiles = walk(join(base, 'case-a-input'));
assert.deepEqual(caseFiles, walk(join(base, 'case-b-input')));
for (const file of caseFiles.filter(file => file !== 'architecture-decision.md')) assert.equal(readFileSync(join(base, 'case-a-input', file), 'utf8'), readFileSync(join(base, 'case-b-input', file), 'utf8'), file);
const policyA = readFileSync(join(base, 'case-a-input/architecture-decision.md'), 'utf8');
const policyB = readFileSync(join(base, 'case-b-input/architecture-decision.md'), 'utf8');
assert.equal(policyA.replace('policy is: permitted.', 'policy is: forbidden.'), policyB);
const latest = JSON.parse(readFileSync(join(base, 'latest-technical-results.json'), 'utf8'));
const currentJava = [...readFileSync(join(root, 'references/boundary-and-contract-tests.md'), 'utf8').matchAll(/```java\r?\n([\s\S]*?)```/g)][0][1];
assert.equal(createHash('sha256').update(currentJava).digest('hex'), latest.extractedJavaSha256);
console.log(JSON.stringify({ status: 'PASS', issues: 0, files: loaded.pkg.files.length, markdown: loaded.pkg.files.filter(file => file.path.endsWith('.md')).length, links, version: loaded.pkg.manifest.version, baseline, final, changed, pair: { filesPerInput: caseFiles.length, changedOnly: 'architecture-decision.md: permitted -> forbidden' }, finalJavaMatchesExecuted: true }, null, 2));

